import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

function DetailDrawer({ id, role, onClose }: { id: number; role: string; onClose: () => void }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', '/approval-documents/' + id, role),
    [id],
  );
  return (
    <Drawer title="완료문서 상세" onClose={onClose}>
      {loading && <p>불러오는 중입니다.</p>}
      {error && <ErrorText text={error} />}
      {data && (
        <Pairs
          items={[
            ['결재문서 ID', String(data.approvalDocumentId ?? '')],
            ['문서 제목', String(data.title ?? '')],
            ['결재 진행 상태', <Badge value={data.approvalStatus} />],
            ['문서 본문', <div>{String(data.body ?? '')}</div>],
          ]}
        />
      )}
    </Drawer>
  );
}

export default function FnSfr04009Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [drafterId, setDrafterId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selectedId, setSelectedId] = useState<number | null>(null);

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/approval-documents', role, undefined, {
        approvalStatus: '완료',
        ...applied,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );

  const search = () => {
    if (startDate && endDate && startDate > endDate) {
      notify('조회 시작일이 종료일보다 늦습니다.');
      return;
    }
    setPage(0);
    setApplied({ startDate, endDate, drafterId });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setDrafterId('');
    setPage(0);
    setApplied({});
  };

  const columns: Column[] = [
    { key: 'documentNumber', label: '문서번호' },
    { key: 'title', label: '문서 제목' },
    { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
    { key: 'drafterId', label: '기안자', render: (r) => <RefName table="employee" role={role} value={r.drafterId} /> },
    { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r.submittedAt} time /> },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>완료 문서</h2>
        <Tiles items={[['조회된 완료문서', data ? String(data.total) : '-']]} />
      </section>
      <section className="box span-8">
        <h2>문서함</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="기안자">
            <LookupSelect table="employee" role={role} value={drafterId} onChange={setDrafterId} />
          </Field>
        </Filters>
        <Band total={data?.total} />
        {error && <ErrorText text={error} />}
        <DataTable
          columns={columns}
          rows={data?.items ?? []}
          onRowClick={(r) => setSelectedId(Number(r.approvalDocumentId))}
          empty={loading ? '불러오는 중입니다.' : '완료된 문서가 없습니다.'}
        />
        <Pager page={data?.page ?? page} size={data?.size ?? SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {selectedId !== null && (
        <DetailDrawer id={selectedId} role={role} onClose={() => setSelectedId(null)} />
      )}
    </div>
  );
}
